    prompt = payload["text"]
    try:
        bedrock_client = client('bedrock-runtime', region_name=config.get('region') or os.environ['AWS_REGION'])
        response = bedrock_client.invoke_model(
            modelId='amazon.titan-text-express-v1',
            body={
                'inputText': prompt,
