import os
from boto3 import client


def get_bedrock_client(region=None):
    region = region or os.environ.get('AWS_REGION')
    return client('bedrock-runtime', region_name=region)


def invoke_model(client, model_id, input_text, max_token_count=4096, temperature=0, top_p=0.9):
    response = client.invoke_model(
        modelId=model_id,
        body={
            'inputText': input_text,
            'textGenerationConfig': {
                'maxTokenCount': max_token_count,
                'temperature': temperature,
                'topP': top_p
            }
        }
    )
    return json.loads(response['body'].read())

from typing import Dict, Any


def normalize_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    return {
        'inputText': payload['text'],
        'textGenerationConfig': {
            'maxTokenCount': payload.get('max_token_count', 4096),
            'temperature': payload.get('temperature', 0),
            'topP': payload.get('top_p', 0.9)
        }
    }


def parse_response(response: Dict[str, Any]) -> Dict[str, Any]:
    return {'outputText': response['results'][0]['outputText']}

import re


def check_prompt_safety(prompt: str) -> bool:
    unsafe_patterns = [
        r'\b(kill|murder|assault|rape|harm)\b',
        r'\b(hate|discriminate)\b',
        r'\b(self-harm|suicide)\b'
    ]
    for pattern in unsafe_patterns:
        if re.search(pattern, prompt, re.IGNORECASE):
            return False
    return True


def check_generated_text_safety(text: str) -> bool:
    unsafe_patterns = [
        r'\b(kill|murder|assault|rape|harm)\b',
        r'\b(hate|discriminate)\b',
        r'\b(self-harm|suicide)\b'
    ]
    for pattern in unsafe_patterns:
        if re.search(pattern, text, re.IGNORECASE):
            return False
    return True

from sentence_transformers import SentenceTransformer


def embed_text(text: str) -> list:
    model = SentenceTransformer('all-MiniLM-L6-v2')
    embedding = model.encode(text)
    return embedding.tolist()
